def segregate_negatives_and_positives(values: list[int]) -> list[int]:
    i, j = 0, len(values) - 1

    while True:
        # Move i forward if the current number is negative
        while i < j and values[i] < 0:
            i += 1
        # Move j backward if the current number is positive
        while i < j and values[j] > 0:
            j -= 1
        # If pointers have crossed, the process is complete
        if i >= j:
            return values
        # Swap the misplaced positive and negative numbers
        values[i], values[j] = values[j], values[i]

def find_optimal_removal(arr: list[int]) -> int:
    if arr.count(0) > 1:
        return min(arr)

    neg = [n for n in arr if n < 0]
    pos = [n for n in arr if n >= 0]

    # If the number of negative numbers is odd
    if len(neg) % 2:
        # If zero is in the array, removing the smallest negative maximizes the product
        return min(neg) if 0 in arr else max(neg)
    else:
        # If the number of negative numbers is even, removing the smallest positive maximizes the product
        return min(pos) if pos else min(neg)

