def max_common_divisors_in_range(a: int, b: int) -> list[int]:
    from itertools import combinations

    def score(sub_gen):
        return lambda n: sum(
            int(''.join(sub)) 
            for length in range(1, len(str(n)) + 1) 
            for sub in sub_gen(str(n), length)
        )

    score1 = score(combinations)
    score2 = score(lambda s, r: (s[i: i+r] for i in range(len(s) - r + 1)))

    def divs(n):
        return set.union(*({d, n // d} for d in range(1, int(n ** 0.5) + 1) if not n % d)) - {1, n}

    div_range = [0]
    for n in range(a, b + 1):
        common_divisors = divs(score1(n)) & divs(score2(n))
        if len(common_divisors) > div_range[0]:
            div_range = [len(common_divisors)]
        if len(common_divisors) == div_range[0]:
            div_range.append(n)

    return div_range

def calculate_group_size(start_size: int, day: int) -> int:
    from math import floor
    # Calculate the group size on the 'day'-th day
    return floor((2 * day + start_size * (start_size - 1)) ** 0.5 + 0.5)

def max_flower_bed_length(garden: list[int]) -> int:
    left, area, record = 0, 0, 1
    for i in range(1, len(garden)):
        if garden[i] < garden[i - 1]:
            left = i
        elif garden[i] > garden[i - 1]:
            area = max(area, record)
            record = i - left
        record += 1
    return max(area, record)

